def contacts_denied_problem(inv: Invitation) -> errors.Problem | None:
    """Возвращает Problem, если доступ к контактам закрыт, иначе None."""
    # Отзыв обработки данных деактивирует аккаунт: любые персональные данные
    # (включая контакты) перестают выдаваться работодателю немедленно (FR-04).
    account = getattr(getattr(inv, "candidate", None), "account", None)
    if account is not None and account.status != AccountStatus.ACTIVE:
        return errors.Problem(
            409, errors.INVALID_STATE, errors.E12_STATE, "Доступ к контактам закрыт",
            detail="Кандидат отозвал обработку данных; контакты недоступны.",
            recovery="none",
        )
    if inv.status != InvitationStatus.ACCEPTED:
        return errors.Problem(
            409, errors.INVALID_STATE, errors.E12_STATE, "Контакты пока закрыты",
            detail="Контакты кандидата открываются только после принятия приглашения.",
            recovery="none",
        )
    if inv.contacts_consented_at is None:
        return errors.Problem(
            409, errors.INVALID_STATE, errors.E12_STATE, "Контакты пока закрыты",
            detail="Кандидат ещё не дал согласие на открытие контактов.",
            recovery="none",
        )
    if inv.contacts_revoked_at is not None:
        return errors.Problem(
            409, errors.INVALID_STATE, errors.E12_STATE, "Доступ к контактам отозван",
            detail="Кандидат отозвал доступ к контактам этой компании.",
            recovery="none",
        )
    return None

def rank_score(candidate: Candidate) -> float:
    test = candidate.test_score or 0.0
    fsp = candidate.fsp_score or 0.0
    # Normalize fsp to 0-100 scale (stub achievements give points up to ~100)
    fsp_norm = min(fsp, 100.0)
    return round(test * 0.7 + fsp_norm * 0.3, 2)

def can_reveal_contacts(invitation: Invitation, candidate: Candidate | None) -> bool:
    """Контакты только после accept, при живом согласии и без отзыва доступа."""
    if invitation.status != InvitationStatus.ACCEPTED:
        return False
    if invitation.contacts_revoked:
        return False
    if not candidate or not candidate.consent_152fz:
        return False
    return True

function canViewContacts(employerId, candidateId, db) {
  // Контакты открываются, если:
  //  1) кандидат сам откликнулся на вакансию этого работодателя;
  //  2) кандидат принял оффер от этого работодателя;
  //  3) кандидат выставил privacy_show_contacts = 1 (явное согласие).
  const cand = db.prepare('SELECT id, privacy_show_contacts FROM candidates WHERE id = ?').get(candidateId);
  if (!cand) return false;
  if (cand.privacy_show_contacts) return true;

  const company = db.prepare('SELECT id FROM employer_companies WHERE id = ?').get(employerId);
  if (!company) return false;

  const acceptedOffer = db.prepare(
    `SELECT 1 FROM offers o
     JOIN vacancies v ON v.id = o.vacancy_id
     WHERE o.candidate_id = $candidateId
       AND v.employer_id = $employerId
       AND o.status = 'accepted'
     LIMIT 1`
  ).get({ candidateId, employerId });
  if (acceptedOffer) return true;

  const application = db.prepare(
    `SELECT 1 FROM applications a
     JOIN vacancies v ON v.id = a.vacancy_id
     WHERE a.candidate_id = $candidateId
       AND v.employer_id = $employerId
     LIMIT 1`
  ).get({ candidateId, employerId });
  if (application) return true;

  return false;
}

function categorizeCandidate(candidate, achievements) {
  const stack = normalizeList(candidate.stack);
  const grade = candidate.verified_grade || candidate.grade;
  const role = candidate.role;
  const achievementsCount = Array.isArray(achievements) ? achievements.length : 0;

  let effectiveGrade = grade;
  if (achievementsCount >= 2 && grade === 'middle') {
    effectiveGrade = 'senior';
  } else if (achievementsCount >= 1 && grade === 'junior') {
    effectiveGrade = 'middle';
  }

  return {
    category: {
      stack: stack.sort(),
      grade: effectiveGrade,
      role,
      work_format: candidate.work_format,
      city: candidate.city || null,
    },
    verified: achievementsCount > 0,
    achievementsCount,
    gradeBoosted: effectiveGrade !== grade,
  };
}

export const finishAttempt = async ({ attemptId, userId }) => {
  const attempt = await repo.getAttempt(attemptId);
  if (!attempt || attempt.user_id !== userId) {
    const err = new Error('not_found'); err.code = 'NOT_FOUND'; throw err;
  }
  if (attempt.status !== 'in_progress') {
    return { attempt, breakdown: await repo.listAnswers(attemptId) };
  }

  const answers = await repo.listAnswers(attemptId);
  const total = answers.reduce((s, a) => s + (a.score || 0), 0);
  const score = answers.length ? Math.round(total / answers.length) : 0;

  const passed = score >= PASS_THRESHOLD;
  const awardedGrade = passed
    ? attempt.target_grade_id
    : LOWER_GRADE[attempt.target_grade_id];  // не понижаем принудительно, только предлагаем

  const finished = await repo.finishAttempt({
    id: attemptId,
    awardedGradeId: passed ? attempt.target_grade_id : null,
    score,
    status: passed ? 'passed' : 'failed',
  });

  return {
    attempt: finished,
    score,
    passed,
    awarded_grade_id: awardedGrade,
    suggested_lower: !passed ? LOWER_GRADE[attempt.target_grade_id] : null,
    breakdown: answers.map(a => ({
      question_id: a.question_id,
      prompt: a.prompt,
      kind: a.kind,
      options: a.options,
      correct: a.correct,
      payload: a.payload,
      is_correct: a.is_correct,
      score: a.score,
    })),
  };
};
